import type { BankItem } from './types';
import { READING_BANK_EARLY } from './readingBankEarly';

/**
 * More grade 1-2 English reading / language questions, so young readers see
 * fewer repeats. Same rules as READING_BANK_EARLY: the difficulty is the
 * school grade (1 = grade 1, 2 = grade 2), and figurative language starts in
 * grade 2.
 */
function q(topic: string, grade: 1 | 2, prompt: string, answer: string, wrong: string[], explanation: string): BankItem {
  return { topic, difficulty: grade, prompt, answer, wrong, explanation };
}

